"use strict";
function split(line) {
  var out = [], start = 0;
  for (var i = 0; i <= line.length; i++) {
    if (i === line.length || line.charAt(i) === ",") { out.push(line.slice(start, i)); start = i + 1; }
  }
  return out;
}
exports.parse = function (text) {
  var lines = [], start = 0;
  for (var i = 0; i < text.length; i++) if (text.charAt(i) === "\n") { lines.push(text.slice(start, i)); start = i + 1; }
  var head = split(lines[0]), rows = [];
  for (var j = 1; j < lines.length; j++) {
    var cells = split(lines[j]), row = {};
    for (var k = 0; k < head.length; k++) row[head[k]] = cells[k];
    rows.push(row);
  }
  return rows;
};
exports.version = require("./package.json").version;
